import {
    type ts,
    Shape,
    type Keys as IKeys,
    KeysRegistry,
    type CoalesceKeys,
    type Formatter,
} from '@servicenow/sdk-build-core'
import type { Project } from '../project'

export class Keys implements IKeys {
    private readonly keys: KeysRegistry

    constructor(project: Project) {
        this.keys = new KeysRegistry(
            project.getCompiler(),
            {
                rootDir: project.getRootDir(),
                config: project.getConfig(),
                package: project.getPackage(),
            },
            project.getFileSystem()
        )
    }

    queryExplicitId(table: string, key: string | number | Shape): string | undefined {
        return this.keys.queryExplicitId(
            table,
            key instanceof Shape
                ? (key.ifString() ?? key.asNumber('Explicit key must be a string or number')).getValue()
                : key
        )
    }

    registerExplicitId(table: string, key: string | number | Shape, guidOverride?: string): string {
        if (key instanceof Shape) {
            return this.keys.registerExplicitId(
                table,
                (key.ifString() ?? key.asNumber('Explicit key must be a string or number')).getValue(),
                guidOverride
            )
        } else {
            return this.keys.registerExplicitId(table, key, guidOverride)
        }
    }

    deleteExplicitId(table: string, key: string | number, guidOverride?: string): string {
        return this.keys.deleteExplicitId(table, key, guidOverride)
    }

    queryCoalesceId(table: string, key: CoalesceKeys): string | undefined {
        return this.keys.queryCompositeId(table, key)
    }

    registerCoalesceId(table: string, key: CoalesceKeys, guidOverride?: string): string {
        return this.keys.registerCompositeId(table, key, guidOverride)
    }

    deleteCoalesceId(table: string, key: CoalesceKeys, guidOverride?: string): string {
        return this.keys.deleteCompositeId(table, key, guidOverride)
    }

    getEffectiveDeletedKeys(): Now.Internal.AnyKey[] {
        return this.keys.getEffectiveDeletedKeys()
    }

    getSourceFile(): ts.SourceFile {
        return this.keys.getSourceFile()
    }

    getFilePath(): string {
        return this.keys.getSourceFile().getFilePath()
    }

    getValue(): Now.Internal.KeysRegistry {
        return this.keys.getValue()
    }

    async commit(formatter?: Formatter): Promise<void> {
        await this.keys.commit(formatter)
    }

    reload(): void {
        this.keys.reload()
    }
}
